from datetime import datetime, timezone, timedelta

class Time(datetime):
    """ Represents a time value with nanosecond precision and timezone information. """

    @staticmethod
    def hydrate_time(nanoseconds, tz=None):
        """ Hydrator for `Time` and `LocalTime` values.

        Parameters:
            nanoseconds (int): The nanoseconds since the epoch.
            tz (timezone): The timezone, if applicable.

        Returns:
            Time: The hydrated `Time` object.
        """
        if tz is None:
            tz = timezone.utc

        dt = datetime.fromtimestamp(nanoseconds / 1e9, tz)
        return Time(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, tzinfo=tz)

