def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to even (also known as round half to nearest even or银行家舍入法).

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 1 == 0:
        return int(n)
    else:
        fractional_part = abs(n) % 1
        if fractional_part < 0.5:
            return int(n)
        elif fractional_part > 0.5:
            return int(n) + 1
        else:
            return int(n) if int(n) % 2 == 0 else int(n) + 1

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, with ties going to the nearest even number.

    :param n: The number to round.
    :return: The rounded number.
    """
    from math import floor, ceil
    fractional_part = n % 1
    if fractional_part == 0.5:
        return floor(n) if n % 2 == 0 else ceil(n)
    else:
        return round(n)

