            xml = f'<{name}>'
            for field in fields:
                xml += f'<{field}>{getattr(self, field)}</{field}>'
            xml += f'</{name}>'
            if self.srid in srid_map:
                xml = f'<srid>{srid_map[self.srid]}</srid>{xml}'
            return xml

    return Point

