def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import subprocess

    if len(cmd) == 0:
        return cmd

    if cmd[0].startswith('#!'):
        first_arg = cmd[0]
        if os.name == 'nt':
            # Windows does not parse shebangs, so we need to fix it
            cmd = (os.path.basename(cmd[0]),) + cmd[1:]
            if ' ' in cmd[0]:
                raise ValueError("Windows path with spaces in shebang is not supported")
            if not os.path.isabs(cmd[0]):
                cmd = (os.path.abspath(cmd[0]),) + cmd[1:]
            try:
                with open(cmd[0], 'r') as f:
                    first_line = f.readline()
                    if not first_line.strip().startswith('#!'):
                        raise ValueError("File does not have a valid shebang")
            except FileNotFoundError:
                raise FileNotFoundError("Shebang file not found")
        elif not first_arg.startswith('/usr'):
            # On Unix-like systems, shebangs should be prefixed with /usr
            first_arg = '/usr' + first_arg

    normalized_cmd = (first_arg,) + cmd[1:]
    normalized_cmd = tuple(os.path.normpath(arg) for arg in normalized_cmd)

    return normalized_cmd

