def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class _TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.cache = {}
            self.access_order = []

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, tuple(kwargs.items())) if self.typed else args
                if key not in self.cache:
                    self.cache[key] = (func(*args, **kwargs), self.timer())
                elif self.timer() - self.cache[key][1] > self.ttl:
                    self.cache[key] = (func(*args, **kwargs), self.timer())
                else:
                    self.access_order.remove(key)
                    self.access_order.append(key)
                if len(self.cache) > self.maxsize:
                    oldest_key = self.access_order.pop(0)
                    del self.cache[oldest_key]
                return self.cache[key][0]
            return wrapper

    return _TTLCache(maxsize, ttl, timer, typed)

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise TypeError('maxsize must be a non-negative integer')
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise TypeError('ttl must be a non-negative number')
    if not callable(timer):
        raise TypeError('timer must be a callable')

    cache = {}
    last_access = {}

    def wrapper(func):
        @functools.wraps(func)
        def memoized_func(*args, **kwargs):
            key = (func, args, frozenset(kwargs.items()))
            if typed:
                key += type(args), type(kwargs)

            if key in cache:
                last_access[key] = timer()
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            last_access[key] = timer()

            if len(cache) > maxsize:
                oldest_key = min(last_access, key=last_access.get)
                del cache[oldest_key]
                del last_access[oldest_key]

            return result

        def prune_cache():
            current_time = timer()
            expired_keys = [key for key, access_time in last_access.items() if current_time - access_time > ttl]
            for key in expired_keys:
                del cache[key]
                del last_access[key]

        memoized_func.prune_cache = prune_cache

        return memoized_func

    return wrapper

