def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    _NOT_FOUND = object()

    class CacheInfo:
        __slots__ = ('hits', 'misses')

        def __init__(self):
            self.hits = 0
            self.misses = 0

        def __repr__(self):
            return f'CacheInfo(hits={self.hits}, misses={self.misses})'

        __str__ = __repr__

        def __eq__(self, other):
            return (
                isinstance(other, CacheInfo)
                and other.hits == self.hits
                and other.misses == self.misses
            )

        def __ne__(self, other):
            return not self == other

    class TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.cache = {}
            self.expiry = {}
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self._cacheinfo = CacheInfo()

        def __getitem__(self, key):
            now = self.timer()
            value = self.cache.get(key, _NOT_FOUND)
            if value is _NOT_FOUND:
                self._cacheinfo.misses += 1
                raise KeyError(key)
            elif now - self.expiry[key] > self.ttl:
                del self.cache[key]
                del self.expiry[key]
                self._cacheinfo.misses += 1
                raise KeyError(key)
            else:
                self.cache.move_to_end(key)
                self._cacheinfo.hits += 1
                return value

        def __setitem__(self, key, value):
            now = self.timer()
            if key in self.cache:
                del self.cache[key]
                del self.expiry[key]
            if self.maxsize is not None:
                while len(self.cache) >= self.maxsize:
                    self.cache.popitem(last=False)
                    del self.expiry[next(iter(self.cache))]
            self.cache[key] = value
            self.expiry[key] = now

        def __delitem__(self, key):
            del self.cache[key]
            del self.expiry[key]

        def __contains__(self, key):
            now = self.timer()
            try:
                value = self.cache[key]
                if now - self.expiry[key] > self.ttl:
                    raise KeyError(key)
                else:
                    self.cache.move_to_end(key)
                    return True
            except KeyError:
                return False

        def __iter__(self):
            now = self.timer()
            for key in reversed(list(self.cache.keys())):
                if now - self.expiry[key] <= self.ttl:
                    yield key
                else:
                    del self.cache[key]
                    del self.expiry[key]

        def __len__(self):
            now = self.timer()
            for key in list(self.cache.keys()):
                if now - self.expiry[key] > self.ttl:
                    del self.cache[key]
                    del self.expiry[key]
            return len(self.cache)

        @property
        def cache_info(self):
            return self._cacheinfo

    def decorator(func):
        def wrapper(*args, **kwargs):
            if typed:
                k = args if args else kwargs
            else:
                k = args + tuple(kwargs.items())

            def get_or_create_key(args, kwargs):
                if typed:
                    return tuple(args)
                else:
                    return (tuple(args), tuple(sorted(kwargs.items())))

            key = get_or_create_key(args, kwargs)
            cache = getattr(func, '__dict__', {})
            if '_cache' not in cache:
                cache['_cache'] = TTLCache(maxsize, ttl, timer, typed)
            cache = cache['_cache']

            try:
                return cache[key]
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = value
                return value

        wrapper.__dict__ = func.__dict__
        return _lru_cache_wrapper(wrapper)

    return decorator

