@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    if not isinstance(e, Exception):
        raise ValueError("The provided object is not an exception instance.")

    def format_traceback(tb, level=0):
        if level >= max_level:
            return "..."
        return "".join(traceback.format_tb(tb, max_path_level)).strip()

    try:
        exc_type, exc_value, exc_traceback = sys.exc_info()
        tb = format_traceback(exc_traceback)
        return f"{e}: {tb}"
    except Exception as formatting_error:
        return f"Error formatting exception: {formatting_error}"

