def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a set to keep track of unique bases
    bases = set()
    for cls in classes:
        bases.update(cls.__bases__)

    # Find the minimum set of bases
    while True:
        changed = False
        for cls in classes:
            cls_bases = set(cls.__bases__)
            if bases.issubset(cls_bases):
                classes.remove(cls)
                bases.update(cls_bases)
                changed = True
                break
        if not changed:
            break

    # Sort the classes by their name
    classes.sort(key=lambda cls: cls.__name__)

    return classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    if not classes:
        return []

    graph = {cls: set(superclass) for cls in classes for superclass in cls.__bases__}
    dependents = {cls: set() for cls in graph}

    for cls, supers in graph.items():
        for superclass in supers:
            dependents[superclass].add(cls)

    stack = [cls for cls in graph if not dependents[cls]]
    minimal = []

    while stack:
        cls = stack.pop()
        minimal.insert(0, cls)
        for dependent in dependents[cls]:
            dependents[dependent].remove(cls)
            if not dependents[dependent]:
                stack.append(dependent)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    subclasses = any(issubclass(c, base) for c in classes for base in classes)

    while subclasses:
        for cls in classes:
            if any(issubclass(c, cls) for c in classes if c != cls):
                classes.remove(cls)
                break
        else:
            break

        subclasses = any(issubclass(c, base) for c in classes for base in classes)

    return classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    classes = set(classes)  # Remove duplicates
    ordered_classes = []

    while classes:
        next_classes = set()
        for cls in classes:
            cls_bases = set(cls.__bases__)
            if cls_bases.issubset(ordered_classes):
                ordered_classes.append(cls)
            else:
                next_classes.update(cls_bases)
        classes = next_classes

    return ordered_classes

