    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """

    if self.errors:
        if 'error' not in context:
            context['error'] = {}
        for key, value in self.errors.items():
            if key not in context['error']:
                context['error'][key] = {}
            for subkey, subvalue in value.items():
                context['error'][key][subkey] = subvalue

    if self.value:
        if 'value' not in context:
            context['value'] = {}
        for key, value in self.value.items():
            if key not in context['value']:
                context['value'][key] = value
            else:
                if isinstance(context['value'][key], dict):
                    context['value'][key].update(value)
                else:
                    context['value'][key] = value

    if self.x:
        if 'error' not in context:
            context['error'] = {}
        context['error']['x'] = {'index': self.x}

    if self.y:
        if 'error' not in context:
            context['error'] = {}
        context['error']['y'] = {'index': self.y}

    if self.z:
        if 'error' not in context:
            context['error'] = {}
        context['error']['z'] = {'index': self.z}

