def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    errors = []
    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, str):
                    errors.append({str(v): 'expected string or bytes-like object'})
        elif not isinstance(value, str):
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError("Validation errors occurred in the labels.", errors)

def _validate_labels(labels):
    errors = []
    import re

    KEY_PATTERN = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')

    def validate_key(key):
        if not isinstance(key, str) or not KEY_PATTERN.match(key):
            errors.append({"key": key, "value": "Label key '{}' does not match the regex pattern '{}'".format(key, KEY_PATTERN.pattern)})
            return False
        return True

    def validate_value(value):
        if not isinstance(value, (str, bytes)):
            errors.append({"value": value, "value": "expected string or bytes-like object"})
            return False
        return True

    for key, value in labels.items():
        if isinstance(value, list):
            for v in value:
                if not validate_value(v):
                    errors.append({"key": key, "value": "Item in list for key '{}' does not pass validation".format(key)})
        else:
            if not validate_value(value):
                errors.append({"key": key, "value": "Value for key '{}' does not pass validation".format(key)})

    if errors:
        raise ValidationError("ValidationError: {}".format(errors))

