import re
from typing import Dict, List

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(self, "\n".join([f"{k}: {v}" for k, v in messages]))

def _validate_labels(labels: Dict) -> None:
    errors = []

    for key, value in labels.items():
        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
        else:
            if not isinstance(value, str):
                errors.append({str(value): 'expected string or bytes-like object'})

        if not re.match(r'^[a-zA-Z0-9_\-:.]*$', key):
            errors.append({'$' + key: "Label key '{}' does not match the regex '[a-zA-Z0-9_\-:.]*'".format(key)})

        if isinstance(value, list):
            if not re.match(r'^[a-zA-Z0-9_\-:.]*$', value[0]):
                errors.append({'$' + value[0]: "Label value '{}' does not match the regex '[a-zA-Z0-9_\-:.]*'".format(value[0])})
        else:
            if not re.match(r'^[a-zA-Z0-9_\-:.]*$', value):
                errors.append({'$' + value: "Label value '{}' does not match the regex '[a-zA-Z0-9_\-:.]*'".format(value)})

