def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field in observer_schema:
        if field in response:
            if isinstance(response[field], dict):
                if response[field] not in last_applied_manifest:
                    last_applied_manifest.append(response[field])
                update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response[field])
            elif isinstance(response[field], list):
                for item in response[field]:
                    if item not in last_applied_manifest:
                        last_applied_manifest.append(item)
                    update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, item)
            else:
                if response[field] not in last_applied_manifest:
                    last_applied_manifest.append(response[field])

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for observed_field in observer_schema:
        if observed_field in response:
            if isinstance(last_applied_manifest, list):
                if observed_field not in last_applied_manifest:
                    last_applied_manifest.append({observed_field: response[observed_field]})
            elif isinstance(last_applied_manifest, dict):
                if observed_field not in last_applied_manifest:
                    last_applied_manifest[observed_field] = response[observed_field]
            else:
                raise ValueError("last_applied_manifest must be a list or a dict")

    for observed_subfield in response:
        if observed_subfield in observer_schema:
            update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response[observed_subfield])

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """

    for field, value in observer_schema.items():
        if field in response:
            if isinstance(value, dict):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = {}
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], value, response[field])
            elif isinstance(value, list):
                if field not in last_applied_manifest:
                    last_applied_manifest[field] = []
                update_last_applied_manifest_list_from_resp(last_applied_manifest[field], value, response[field])
            else:
                last_applied_manifest[field] = response[field]
        else:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")

