def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """

    if isinstance(sql, bytes):
        sql = sql.decode()

    if self.SQLParams.in_style == NamedParameterStyle:
        if not isinstance(params, Mapping):
            raise ValueError("params must be a Mapping when using named parameters")

        formatted_sql = sql
        out_params = {}

        for key, value in params.items():
            placeholder = ":" + key
            formatted_sql = formatted_sql.replace(placeholder, self._format_value(value))
            out_params[key] = value

    elif self.SQLParams.in_style == OrdinalParameterStyle:
        if not isinstance(params, Sequence):
            raise ValueError("params must be a Sequence when using ordinal parameters")

        formatted_sql = sql
        out_params = list(params)

        for i, value in enumerate(params):
            placeholder = "?" * (i + 1)
            formatted_sql = formatted_sql.replace(placeholder, self._format_value(value))

    else:
        raise ValueError(f"Unsupported in_style: {self.SQLParams.in_style}")

    return formatted_sql, out_params

def _format_value(self, value):
    if isinstance(value, str):
        return f"'{value}'"
    elif isinstance(value, (int, float)):
        return str(value)
    elif isinstance(value, bool):
        return str(value).lower()
    elif isinstance(value, list):
        return f"({', '.join(map(repr, value))})"
    elif isinstance(value, tuple):
        return f"({', '.join(map(repr, value))})"
    elif value is None:
        return "NULL"
    else:
        raise ValueError(f"Unsupported value type: {type(value)}")

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if self.SQLParams.in_style == 'named':
        if not isinstance(params, Mapping):
            raise ValueError("params must be a dictionary for named parameter style")
        formatted_sql = sql
        formatted_params = {}
        for key, value in params.items():
            placeholder = self._get_named_placeholder(key)
            formatted_sql = formatted_sql.replace(placeholder, self._format_value(value))
            formatted_params[key] = self._prepare_out_param(value)
        return formatted_sql, formatted_params
    elif self.SQLParams.in_style == 'ordinal':
        if not isinstance(params, Sequence):
            raise ValueError("params must be a sequence for ordinal parameter style")
        formatted_sql = sql
        formatted_params = []
        for i, value in enumerate(params):
            placeholder = self._get_ordinal_placeholder(i + 1)
            formatted_sql = formatted_sql.replace(placeholder, self._format_value(value))
            formatted_params.append(self._prepare_out_param(value))
        return formatted_sql, formatted_params
    else:
        raise ValueError(f"Unsupported parameter style: {self.SQLParams.in_style}")

    def _get_named_placeholder(self, key: Union[str, int]) -> str:
        return f':{key}'

    def _get_ordinal_placeholder(self, index: int) -> str:
        return f'${index}'

    def _format_value(self, value: Any) -> str:
        if isinstance(value, bytes):
            return value.decode('utf-8')
        return str(value)

    def _prepare_out_param(self, value: Any) -> Any:
        if isinstance(value, bytes):
            return value
        return str(value)

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if self.SQLParams.in_style == ParameterStyle.NAMED:
        if not isinstance(params, Mapping):
            raise ValueError("params must be a Mapping when using named parameter style")
        formatted_sql = sql % {f":{key}": value for key, value in params.items()}
        out_params = {i: value for i, value in enumerate(params)}
    elif self.SQLParams.in_style == ParameterStyle.ORDINAL:
        if not isinstance(params, Sequence):
            raise ValueError("params must be a Sequence when using ordinal parameter style")
        formatted_sql = sql % params
        out_params = list(params)
    else:
        raise ValueError("Unsupported parameter style")

    return formatted_sql, out_params

import re
from typing import Any, AnyStr, Iterable, List, Mapping, Sequence, Tuple, Union

class SQLParams:
    in_style: str
    out_style: str

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """

    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    out_params: List[Union[Dict[Union[str, int], Any], List[Sequence[Any]]]] = []

    if isinstance(many_params, Iterable):
        first_param = next(iter(many_params), None)
        if isinstance(first_param, Mapping) and isinstance(first_param, Sequence):
            raise ValueError("Params must be either a mapping or a sequence")

        if isinstance(first_param, Mapping):
            for params in many_params:
                if not isinstance(params, Mapping):
                    raise ValueError("Params must be a mapping")
                out_param = {}
                for key, value in params.items():
                    if not isinstance(key, (str, int)):
                        raise ValueError("Parameter keys must be strings or integers")
                    out_param[key] = value
                out_params.append(out_param)

        elif isinstance(first_param, Sequence):
            for params in many_params:
                if not isinstance(params, Sequence):
                    raise ValueError("Params must be a sequence")
                out_params.append(list(params))

    else:
        raise ValueError("many_params must be an iterable")

    formatted_sql = sql
    if self.params.in_style == 'named' and self.params.out_style == 'ordinal':
        for i, param in enumerate(out_params):
            if isinstance(param, Mapping):
                param_str = ', '.join(f"{key} = :{i+1}" for key in param)
                formatted_sql = re.sub(r':{0}'.format(i+1), param_str, formatted_sql)
            else:
                param_str = ', '.join(f"{i+1}" for _ in param)
                formatted_sql = re.sub(r':{0}'.format(i+1), param_str, formatted_sql)

    elif self.params.in_style == 'ordinal' and self.params.out_style == 'named':
        for i, param in enumerate(out_params):
            if isinstance(param, Mapping):
                param_str = ', '.join(f":{key} = {i+1}" for key in param)
                formatted_sql = re.sub(r':{0}'.format(i+1), param_str, formatted_sql)
            else:
                param_str = ', '.join(f"{i+1}" for _ in param)
                formatted_sql = re.sub(r':{0}'.format(i+1), param_str, formatted_sql)

    if isinstance(formatted_sql, bytes):
        formatted_sql = formatted_sql.encode('utf-8')

    return formatted_sql, out_params

