    """Render the given version pieces as HTML."""

    html = []
    for piece in pieces:
        if isinstance(piece, str):
            html.append(piece)
        elif isinstance(piece, dict):
            if piece['type'] == 'bold':
                html.append('<strong>{}</strong>'.format(piece['content']))
            elif piece['type'] == 'italic':
                html.append('<em>{}</em>'.format(piece['content']))
        else:
            raise ValueError("Unsupported piece type: {}".format(type(piece)))

    return ''.join(html)

