    versionfile_abs = os.path.abspath(versionfile_source)
    versionfile_dir = os.path.dirname(versionfile_abs)
    versionfile_base = os.path.basename(versionfile_abs)
    keywords = get_keywords(versionfile_abs)
    return VersioneerConfig(
        versionfile_abs, versionfile_dir, versionfile_base, keywords)

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""

    def wrapper(*args, **kwargs):
        if vcs not in VCS_HANDLERS:
            VCS_HANDLERS[vcs] = []
        VCS_HANDLERS[vcs].append(method)
        return method(*args, **kwargs)

    return wrapper

