def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    for obj in self.iter_objects():
        num_objects += 1
        valid = True

        if validate_objects:
            try:
                obj.validate()
            except Exception as e:
                if show_warnings:
                    warnings.warn(str(e))
                valid = False

        if check_digests and hasattr(obj, 'digest'):
            try:
                if not obj.digest_matches():
                    if show_warnings:
                        warnings.warn(f"Digest mismatch for object {obj.id}")
                    valid = False
            except Exception as e:
                if show_warnings:
                    warnings.warn(str(e))
                valid = False

        if valid:
            good_objects += 1

    return num_objects, good_objects

