def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.isdigit():
        return str(int(version) + 1)
    else:
        return version + '-1'

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.isdigit():
        return str(int(version) + 1)
    else:
        match = re.match(r'(\d+)(.*)', version)
        if match:
            number = int(match.group(1))
            suffix = match.group(2)
            return str(number + 1) + suffix
        else:
            return version + '1'

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    num = int(version)
    updated_num = num + 1
    if version.startswith('0'):
        return '0' * (len(version) - len(str(updated_num))) + str(updated_num)
    else:
        return str(updated_num)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = None
    content_digests = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory.json')
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory file not found for version {version_dir}")

        with open(inventory_path, 'r') as f:
            inventory = json.load(f)

        if root_inventory is None:
            root_inventory = inventory
        else:
            self._compare_inventories(root_inventory, inventory)

        self._record_content_digests(inventory, content_digests)

    for version_dir in version_dirs:
        self._validate_content(version_dir, content_digests)

    def _compare_inventories(self, root_inventory, inventory):
        InventoryComparer.compare(root_inventory, inventory)

    def _record_content_digests(self, inventory, content_digests):
        for entry in inventory.get('entries', []):
            if entry['type'] == 'content':
                content_digests[entry['digest']] = True

    def _validate_content(self, version_dir, content_digests):
        content_dir = os.path.join(version_dir, 'content')
        for filename in os.listdir(content_dir):
            content_path = os.path.join(content_dir, filename)
            if os.path.isfile(content_path):
                with open(content_path, 'rb') as f:
                    content_hash = hashlib.sha256(f.read()).hexdigest()
                    if content_hash not in content_digests:
                        raise ContentDigestMismatchError(f"Content digest mismatch for {filename} in version {version_dir}")

