def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if os.path.isdir(path):
            namaste_file = os.path.join(path, "0=**")
            if os.path.exists(namaste_file):
                with open(namaste_file, 'r') as f:
                    first_line = f.readline().strip()
                    if first_line == "ocfl_version=1.0":
                        return 'ocfl_root'
                    elif first_line == "storage=1.0":
                        return 'ocfl_object'
                    else:
                        return 'unknown_directory_type'
            else:
                return 'standard_directory'
        elif os.path.isfile(path):
            return 'file'
        else:
            return 'nonexistent'
    except Exception as e:
        return str(e)

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path}"

        if os.path.isfile(path):
            return 'file'

        namaste_file_path = os.path.join(path, '0=', '*')

        if not os.path.isfile(namaste_file_path):
            return f"No Namaste file found: {namaste_file_path}"

        with open(namaste_file_path, 'r') as file:
            first_line = file.readline().strip()
            if first_line == 'ocfl_version "1.0"':
                if 'storage_root' in open(os.path.join(path, 'manifest.json')).read():
                    return 'root'
                elif 'object_uuid' in open(os.path.join(path, 'manifest.json')).read():
                    return 'object'
            else:
                return f"Unexpected Namaste file content: {first_line}"

    except Exception as e:
        return f"Error: {str(e)}"

    return "Unknown directory type"

import os

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if os.path.isdir(path):
            namaste_file = os.path.join(path, '0=*')
            if os.path.isfile(namaste_file):
                with open(namaste_file, 'r') as f:
                    content = f.read().strip()
                    if content == 'storageRoot':
                        return 'root'
                    elif content == 'object':
                        return 'object'
        elif os.path.isfile(path):
            return 'file'
    except Exception as e:
        return str(e)

    return 'unknown'

