def deep_merge(mapping1, mapping2):
    result = mapping1.copy()
    for key, value in mapping2.items():
        if key in result and isinstance(result[key], ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
            result[key] = deep_merge(result[key].value, value.value)
        else:
            result[key] = value
    return result

def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    def merge(node1, node2):
        if isinstance(node1, MappingNode) and isinstance(node2, MappingNode):
            for key, value in node2.value:
                key_value = next((x for x in node1.value if x[0] == key), None)
                if key_value:
                    key_value[1] = merge(key_value[1], value)
                else:
                    node1.value.append([key, value])
        else:
            node1 = node2
        return node1

    merged = {}
    for key, value in nodes:
        if key.value in merged:
            merged[key.value] = merge(merged[key.value], value)
        else:
            merged[key.value] = value

    return [(key, value) for key, value in merged.items()]

