def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("The alphabet cannot be empty.")

    result = ""
    base = len(alphabet)

    if number == 0:
        return alphabet[0]

    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if padding and len(result) < padding:
        result = (padding - len(result)) * alphabet[0] + result

    return result

