def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    use_ssl = False
    if image_href.startswith('https'):
        use_ssl = True
        image_href = image_href[len('https'):]
    elif image_href.startswith('http'):
        image_href = image_href[len('http'):]
    else:
        raise ValueError("Invalid image href")

    if image_href.startswith('//'):
        image_href = image_href[len('//'):]

    if '?' in image_href:
        image_id, query = image_href.split('?', 1)
        if 'ssl' in query:
            use_ssl = True
    else:
        image_id = image_href

    netloc = ''
    if '/' in image_id:
        netloc, image_id = image_id.split('/', 1)

    return image_id, netloc, use_ssl

