    '''Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.'''

    configurations = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                try:
                    config = json.load(file)
                    if resolve_env:
                        config = resolve_environment_variables(config)
                    configurations[filename] = config
                except json.JSONDecodeError as e:
                    error = logging.LogRecord(logging.ERROR, f"Error parsing {filename}: {e}", filename=filename, lineno=1)
                    errors.append(error)
        except FileNotFoundError as e:
            error = logging.LogRecord(logging.ERROR, f"File not found: {e}", filename=filename)
            errors.append(error)

    if overrides:
        for filename, config in configurations.items():
            config.update(overrides)

    return configurations, errors

def resolve_environment_variables(config: Dict[str, Any]) -> Dict[str, Any]:
    '''Resolve environment variables in a configuration dictionary.'''
    for key, value in config.items():
        if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
            config[key] = os.getenv(value[2:-1], value)
        elif isinstance(value, dict):
            resolve_environment_variables(value)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    resolve_environment_variables(item)
    return config

import json
import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """

    configurations = {}
    parse_errors = []

    logger = logging.getLogger(__name__)

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as config_file:
                config_data = json.load(config_file)

                if resolve_env:
                    for key, value in config_data.items():
                        if isinstance(value, dict) and 'env' in value:
                            config_data[key] = value['env'].get(value['name'], value['default'])

                if overrides:
                    config_data.update(overrides)

                configurations[config_filename] = config_data

        except Exception as e:
            parse_errors.append(logging.LogRecord(level=logging.ERROR, name=logger.name, pathname=config_filename, lineno=0, msg=str(e), args=(), exc_info=None))

    return configurations, parse_errors

import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import configparser

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        parser = configparser.ConfigParser()
        try:
            parser.read(filename)
            if resolve_env:
                parser.resolve()
            config_dict[filename] = parser
        except configparser.Error as e:
            log_record = logging.LogRecord('configparser', logging.ERROR, filename, e.lineno, str(e), {}, None)
            log_records.append(log_record)

    if overrides:
        for section, options in overrides.items():
            if section in config_dict:
                for key, value in options.items():
                    if key in config_dict[section]:
                        config_dict[section][key] = value

    return config_dict, log_records

