def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    tag_stack = []
    result = []

    for char in text:
        if char == '`':
            if in_code_block:
                result.append(char)
            else:
                in_code_block = True
        elif char == '\n':
            if in_code_block:
                result.append(char)
            else:
                if tag_stack:
                    result.append('<' + '/'.join(tag_stack) + '>')
                tag_stack = []
        elif char == '<' and not in_code_block:
            if result and result[-1] == '<':
                tags.add(char)
            result.append(char)
            tag_stack.append(char[1:])
        elif char == '>' and not in_code_block:
            if tag_stack:
                result.append(char)
                tag_stack.pop()
                if not tag_stack:
                    tags.add(''.join(result[-len(tag_stack):-len(tag_stack)+1]))
            else:
                result.append(char)
        else:
            if not in_code_block:
                if tag_stack:
                    result.append('<' + '/'.join(tag_stack) + '>')
                    tag_stack = []
            result.append(char)

    if replacer:
        result = [replacer(tag) if tag in tags else tag for tag in result]

    return tags, ''.join(result)

from typing import Set, Tuple, Callable, Optional

def find_tags(text: str, replacer: Optional[Callable[[str], str]] = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    in_code_block = False
    result = []
    tag_word = ''

    i = 0
    while i < len(text):
        if text[i:i+3] == '<code>':
            in_code_block = True
            i += 5
        elif text[i:i+6] == '</code>':
            in_code_block = False
            i += 7
        elif not in_code_block and text[i] == '<' and i + 1 < len(text) and text[i+1] != '/':
            j = i + 1
            while j < len(text) and text[j] != '>':
                j += 1
            tag = text[i:j]
            tags.add(tag.strip('<>'))
            if replacer:
                tag_word += replacer(tag.strip('<>'))
            else:
                tag_word += tag
            i = j + 1
        else:
            if not in_code_block and text[i] == '<':
                if tag_word:
                    result.append(tag_word)
                    tag_word = ''
                result.append(text[i])
            elif not in_code_block and text[i] == '>':
                if tag_word:
                    result.append(tag_word)
                    tag_word = ''
                result.append(text[i])
            else:
                tag_word += text[i]
            i += 1

    if tag_word:
        result.append(tag_word)

    return tags, ''.join(result)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    import re
    from urllib.parse import urlparse

    def linkify(text):
        url_pattern = re.compile(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+')
        return re.sub(url_pattern, lambda match: f'<a href="{match.group(0)}" target="_blank">{match.group(0)}</a>', text)

    def add_attributes(text):
        return re.sub(r'\[([^\]]+)\]([^\[]+)', lambda match: f'<span class="link-label">{match.group(1)}</span><a href="{match.group(2)}" target="_blank">{match.group(2)}</a>', text)

    return linkify(add_attributes(text))

import requests
from typing import Optional

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        response.raise_for_status()
        return response.headers.get('Content-Type')
    except requests.exceptions.RequestException:
        return None

