def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""

    # Check if the tag is a valid XML tag name
    if not tag.isalpha():
        return False

    # Check if the tag starts with a letter (valid XML tag names must start with a letter or underscore)
    if not tag[0].isalpha():
        return False

    # Check if the tag contains any invalid characters (XML tag names can only contain letters, digits, hyphens, underscores, colons, and periods)
    if not all(char.isalnum() or char in '-_:.' for char in tag):
        return False

    # If all checks pass, the tag is a valid XML tag name
    return True

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""

    # Check if the tag is not empty
    if not tag:
        return False

    # Check if the tag contains only allowed characters (letters, numbers, hyphens, and underscores)
    if not tag.isalnum() and not '-' in tag and not '_' in tag:
        return False

    # Tag is considered valid
    return True

