import json
from xml.etree import ElementTree as ET
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try parsing as JSON
        data = json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try parsing as XRD
        root = ET.fromstring(document)
        xrd = root.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD')
        if xrd is not None:
            diaspora_id = xrd.find('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Subject').text
            links = xrd.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link')
            data = {
                'diaspora_id': diaspora_id,
                'links': [
                    {
                        'rel': link.get('rel'),
                        'href': link.get('href'),
                        'type': link.get('type')
                    } for link in links
                ]
            }
        else:
            raise ValueError("Invalid Diaspora webfinger document, not a JSON object or XRD.")

    return data

