def _evaluate_condition(self, command_name, condition, args):
    """Evaluate a conditional requirement for an argument.

    :param command_name: the command name.
    :param condition: the condition dictionary.
    :param args: the received input arguments
    :return: bool, whether the condition is matched
    """
    if 'or' in condition:
        return any(self._evaluate_condition(command_name, sub_condition, args) for sub_condition in condition['or'])
    elif 'and' in condition:
        return all(self._evaluate_condition(command_name, sub_condition, args) for sub_condition in condition['and'])
    elif 'not' in condition:
        return not self._evaluate_condition(command_name, condition['not'], args)
    elif isinstance(condition, dict):
        key, value = condition.popitem()
        if key in args:
            if isinstance(value, list):
                return args[key] in value
            else:
                return args[key] == value
    return False

